test('provider rollout borrowed admission refuses null or forged owner without another immutable preparation or provider POST',async()=>{const subject=await api();for(const invalid of [null,Object.freeze({})])await fixture(async input=>{const key='e'.repeat(64),runtimeConfig=runtime();Object.assign(runtimeConfig.edge,{CUEVO_WORKER_WAKE_KEY:key,CUEVO_WORKER_RELEASE_GENERATION:'2'});Object.assign(input.expected,{executionScope:'runtime-rollout',runtimeRollout:{desired:{generation:'2'}}});const lease=Object.freeze({}),session={readState:async()=>({original:{wakeKey:key},pending:{identity:{},runtimeConfigurationSha256:hash(canonicalReleaseReviewJson(runtimeConfig))}})};Object.assign(fixtureState(),{nativeLease:lease,nativeSession:session});const original=globalThis.fetch;let posts=0;globalThis.fetch=async()=>{posts++;throw Error('No provider transport expected');};try{const result=await subject.deployBackendProvidersForRollout({...input,operator,runtimeConfig,vercelToken:'private-vercel-token-provider-fixture',providerToken:'private-supabase-token-provider-fixture'},lease as Parameters<typeof subject.deployBackendProvidersForRollout>[1],invalid as Parameters<typeof subject.deployBackendProvidersForRollout>[2]);assert.equal(result.status,'REQUIRES_REVIEW');assert.equal(admissionPreparations,0);assert.equal(admissionDisposals,0);assert.equal(posts,0);}finally{globalThis.fetch=original;}});});

test('ordinary provider schema borrower must retain its distinct SCHEMA scope and cannot become a fallback owner',async()=>{const{deployBackendProviders}=await api();for(const mode of ['null','foreign','complete','wrong-mode'])await fixture(async input=>{Object.assign(input.expected,{schemaRecovery:{}});const binding={repoRoot:input.repoRoot,expected:input.expected,prepared:input.preparedApproval,githubToken:input.githubToken},primary=Object.freeze({}) as Parameters<typeof deployBackendProviders>[1];admissionHandles.set(primary!,canonicalReleaseReviewJson({...binding,effectScope:'COMPLETE_BACKEND'}));const schema=mode==='null'?null:Object.freeze({});if(mode==='complete')admissionHandles.set(schema!,canonicalReleaseReviewJson({...binding,effectScope:'COMPLETE_BACKEND'}));if(mode==='wrong-mode')delete(input.expected as{schemaRecovery?:unknown}).schemaRecovery;const original=globalThis.fetch;let effects=0;globalThis.fetch=async()=>{effects++;throw Error('No provider transport expected');};try{const result=await deployBackendProviders({...input,operator,vercelToken:'private-vercel-token-provider-fixture',providerToken:'private-supabase-token-provider-fixture'},primary,schema as Parameters<typeof deployBackendProviders>[2]);assert.equal(result.status,'REQUIRES_REVIEW');assert.equal(admissionPreparations,0);assert.equal(admissionDisposals,0);assert.equal(effects,0);}finally{globalThis.fetch=original;}});});
